/* ---------- helpers ---------- */

function readCookie(name) {
  const hit = document.cookie.split('; ').find((row) => row.startsWith(name + '='));
  return hit ? decodeURIComponent(hit.split('=')[1]) : '';
}

async function getJson(url) {
  const res = await fetch(url, {
    credentials: 'same-origin',
    headers: { Accept: 'application/json', 'X-XSRF-TOKEN': readCookie('XSRF-TOKEN') },
  });
  if (!res.ok) throw new Error(url + ' -> HTTP ' + res.status);
  return res.json();
}

const SEVERITY_ORDER = ['CRITICAL', 'MAJOR', 'MINOR', 'WARNING'];

function worstSeverity(alarms) {
  return SEVERITY_ORDER.find((sev) => alarms.some((a) => a.severity === sev));
}

function plural(n, word) {
  return n + ' ' + word + (n === 1 ? '' : 's');
}

function escapeHtml(text) {
  return String(text).replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
}

// Sensors open on their live measurement charts, the other devices on their alarms.
const MEASUREMENT_DEVICES = ['WATER_LEVEL_DEVICE_ID', 'SOIL_MOISTURE_DEVICE_ID', 'MOSQUITO_DEVICE_ID'];
function deviceUrl(id) {
  // Opens the device in Device Management, which has the built-in Measurements / Alarms / Events tabs
  var tab = MEASUREMENT_DEVICES.indexOf(String(id)) > -1 ? 'measurements' : 'alarms';
  return '/apps/devicemanagement/index.html#/device/' + encodeURIComponent(id) + '/' + tab;
}

function repeats(alarm) {
  return alarm.count || 1;
}

function hoursSince(iso) {
  return Math.round((Date.now() - new Date(iso).getTime()) / 3600000);
}

function shortDate(date) {
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

/* ---------- widget ---------- */

export default class IotDevicesWidget extends HTMLElement {
  connectedCallback() {
    if (!this.shadowRoot) {
      this.attachShadow({ mode: 'open' }).innerHTML = '<style>:host{display:block}' + STYLES + '</style>' + MARKUP;
      this.applySection();
      this.shadowRoot.addEventListener('click', (event) => this.onClick(event));
      this.shadowRoot.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') this.closeInsights();
      });
    }
    this.groups = {};
    this.load();
    this.timer = setInterval(() => this.load(), REFRESH_MS);
  }

  applySection() {
    const label = CATEGORY_LABEL[SECTION];
    if (!label) return;
    const root = this.shadowRoot;
    root.querySelectorAll('.iot-cat[data-cat]').forEach((cat) => {
      if (cat.getAttribute('data-cat') !== SECTION) cat.style.display = 'none';
    });
    root.querySelector('.iot-groups').style.gridTemplateColumns = '1fr';
    root.querySelector('.iot-title').textContent = label + ' Devices';
  }

  disconnectedCallback() {
    clearInterval(this.timer);
  }

  onClick(event) {
    const root = this.shadowRoot;
    if (event.target.closest('[data-insights-open]')) return this.openInsights();
    if (event.target.closest('[data-insights-close]') || event.target.classList.contains('iot-modal')) return this.closeInsights();

    const media = event.target.closest('.iot-media');
    const isLink = event.target.closest('.iot-picker a');
    root.querySelectorAll('.iot-media.is-open').forEach((el) => { if (el !== media) el.classList.remove('is-open'); });
    if (!media || isLink) return;

    const devices = media.devices || [];
    if (devices.length === 1) {
      window.open(deviceUrl(devices[0].id), '_blank');
    } else if (devices.length > 1) {
      media.classList.toggle('is-open');
    }
  }

  async load() {
    try {
      const [inv, alm] = await Promise.all([
        getJson('/inventory/managedObjects?fragmentType=c8y_IsDevice&pageSize=2000&withTotalPages=false'),
        getJson('/alarm/alarms?status=ACTIVE&pageSize=2000&withTotalPages=false'),
      ]);
      this.groups = this.groupDevices(inv.managedObjects || []);
      this.render(alm.alarms || []);
    } catch (err) {
      console.warn('[IoT devices widget] live data not loaded:', err);
    }
  }

  groupDevices(devices) {
    const byName = {};
    Object.keys(DEVICE_NAMES).forEach((key) => {
      DEVICE_NAMES[key].forEach((name) => { byName[name.trim().toLowerCase()] = key; });
    });
    const groups = {};
    Object.keys(DEVICE_NAMES).forEach((key) => { groups[key] = []; });
    devices.forEach((mo) => {
      const key = byName[(mo.name || '').trim().toLowerCase()];
      if (key) groups[key].push(mo);
    });
    return groups;
  }

  allDevices() {
    return Object.keys(this.groups).flatMap((key) => this.groups[key].map((mo) => ({ mo, key })));
  }

  render(alarms) {
    const root = this.shadowRoot;
    const groups = this.groups;
    const alarmsFor = (list) => {
      const ids = new Set(list.map((mo) => mo.id));
      return alarms.filter((a) => a.source && ids.has(a.source.id));
    };
    let totalDevices = 0;
    let totalAlarms = 0;

    root.querySelectorAll('[data-dev]').forEach((card) => {
      const list = groups[card.dataset.dev] || [];
      const active = alarmsFor(list);
      const status = card.querySelector('[data-status]');
      totalDevices += list.length;
      totalAlarms += active.length;

      const media = card.querySelector('.iot-media');
      media.devices = list;
      media.classList.toggle('is-linked', list.length > 0);
      media.querySelectorAll('.iot-open, .iot-picker').forEach((el) => el.remove());
      if (list.length) {
        media.insertAdjacentHTML('beforeend',
          '<span class="iot-open">' + (list.length === 1 ? 'Click here to view device' : 'Click here to choose device') + ' →</span>' +
          (list.length > 1 ? '<div class="iot-picker">' + list.map((mo) =>
            '<a href="' + deviceUrl(mo.id) + '" target="_blank" rel="noopener">' + escapeHtml(mo.name || mo.id) + '</a>').join('') + '</div>' : ''));
      }

      status.className = 'iot-status';
      if (!list.length) {
        status.innerHTML = '<span class="iot-dot"></span>No device linked';
        return;
      }
      const worst = worstSeverity(active);
      status.classList.add(worst ? 'is-' + worst.toLowerCase() : 'is-ok');
      status.innerHTML = '<span class="iot-dot"></span>' +
        (worst ? plural(active.length, (active.every((a) => a.severity === worst) ? worst.toLowerCase() : 'active') + ' alarm') : 'No active alarms') +
        ' <span class="iot-seen">· ' + plural(list.length, 'device') + '</span>';
    });

    Object.keys(CATEGORY_CARDS).forEach((cat) => {
      const note = root.querySelector('[data-cat="' + cat + '"] [data-note]');
      const list = CATEGORY_CARDS[cat].flatMap((key) => groups[key] || []);
      note.innerHTML = '<span>' + plural(list.length, 'device') + '</span><span>' + plural(alarmsFor(list).length, 'active alarm') + '</span>';
    });

    const time = new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
    let shownDevices = totalDevices, shownAlarms = totalAlarms;
    if (CATEGORY_CARDS[SECTION]) {
      const mine = CATEGORY_CARDS[SECTION].flatMap((key) => groups[key] || []);
      shownDevices = mine.length; shownAlarms = alarmsFor(mine).length;
    }
    root.querySelector('[data-summary]').textContent =
      plural(shownDevices, 'device') + ' · ' + plural(shownAlarms, 'active alarm') + ' · updated ' + time;
  }

  /* ---------- weekly insights window ---------- */

  openInsights() {
    const modal = this.shadowRoot.querySelector('.iot-modal');
    const body = modal.querySelector('[data-insights-body]');
    modal.hidden = false;
    modal.querySelector('.iot-modal-close').focus();
    body.innerHTML = '<p class="iot-muted">Analysing the last 7 days…</p>';
    this.loadWeek()
      .then((week) => { body.innerHTML = this.insightsHtml(week); })
      .catch((err) => {
        console.warn('[IoT devices widget] weekly data not loaded:', err);
        body.innerHTML = '<p class="iot-muted">Could not load this week’s data from Cumulocity.</p>';
      });
  }

  closeInsights() {
    const modal = this.shadowRoot.querySelector('.iot-modal');
    if (modal) modal.hidden = true;
  }

  async loadWeek() {
    const to = new Date();
    const from = new Date(to.getTime() - 7 * DAY_MS);
    const range = 'dateFrom=' + encodeURIComponent(from.toISOString()) + '&dateTo=' + encodeURIComponent(to.toISOString());
    const [alm, evt] = await Promise.all([
      getJson('/alarm/alarms?' + range + '&pageSize=2000&withTotalPages=false'),
      getJson('/event/events?' + range + '&pageSize=2000&withTotalPages=false'),
    ]);
    const devices = this.allDevices();
    const ids = new Set(devices.map((d) => d.mo.id));
    return {
      from, to, devices,
      alarms: (alm.alarms || []).filter((a) => a.source && ids.has(a.source.id)),
      events: (evt.events || []).filter((e) => e.source && ids.has(e.source.id)),
    };
  }

  analyse(week) {
    const { devices, alarms, events } = week;
    const keyOf = {};
    const nameOf = {};
    devices.forEach(({ mo, key }) => { keyOf[mo.id] = key; nameOf[mo.id] = mo.name || mo.id; });
    const catOf = (key) => Object.keys(CATEGORY_CARDS).find((c) => CATEGORY_CARDS[c].includes(key));

    const raised = alarms.reduce((sum, a) => sum + repeats(a), 0);
    const critical = alarms.filter((a) => a.severity === 'CRITICAL').reduce((sum, a) => sum + repeats(a), 0);
    const open = alarms.filter((a) => a.status !== 'CLEARED');

    const perCat = {};
    Object.keys(CATEGORY_CARDS).forEach((c) => { perCat[c] = { alarms: 0, critical: 0, open: 0, events: 0 }; });
    alarms.forEach((a) => {
      const c = perCat[catOf(keyOf[a.source.id])];
      c.alarms += repeats(a);
      if (a.severity === 'CRITICAL') c.critical += repeats(a);
      if (a.status !== 'CLEARED') c.open += 1;
    });
    events.forEach((e) => { perCat[catOf(keyOf[e.source.id])].events += 1; });

    const recs = [];
    const add = (priority, area, title, detail) => recs.push({ priority, area, title, detail });

    // 1. Critical alarms left open for more than a day
    open.filter((a) => a.severity === 'CRITICAL' && hoursSince(a.creationTime || a.time) >= 24).forEach((a) => {
      add('high', CATEGORY_LABEL[catOf(keyOf[a.source.id])],
        'Add an escalation step for ' + nameOf[a.source.id],
        'Critical alarm “' + (a.text || a.type) + '” has been open for ' + hoursSince(a.creationTime || a.time) +
        ' h. Let the agent escalate to the on-call team if a critical alarm is not acknowledged within 30 min.');
    });

    // 2. Noisy alarms (same alarm repeated many times)
    alarms.filter((a) => repeats(a) >= 5).sort((a, b) => repeats(b) - repeats(a)).slice(0, 3).forEach((a) => {
      add(a.severity === 'CRITICAL' ? 'high' : 'medium', CATEGORY_LABEL[catOf(keyOf[a.source.id])],
        'Tune the threshold on ' + nameOf[a.source.id],
        '“' + (a.text || a.type) + '” fired ' + repeats(a) + ' times this week. Have the agent group repeats into one incident and review the trigger threshold.');
    });

    // 3. Unauthorized access + camera correlation
    const unauthorized = devices.filter(({ mo }) => /unauthori[sz]ed/i.test(mo.name || '')).map(({ mo }) => mo.id);
    const denied = alarms.filter((a) => unauthorized.includes(a.source.id)).reduce((s, a) => s + repeats(a), 0);
    const cameraAlerts = alarms.filter((a) => keyOf[a.source.id] === 'camera').reduce((s, a) => s + repeats(a), 0);
    if (denied > 0) {
      add(cameraAlerts > 0 ? 'high' : 'medium', 'Security & Access', 'Correlate denied entries with camera footage',
        denied + ' unauthorized permit attempts' + (cameraAlerts ? ' and ' + cameraAlerts + ' camera alerts' : '') +
        ' this week. The agent should attach the nearest camera clip to every denied entry before notifying security.');
    }

    // 4. Pest control follow-up
    const mosquito = alarms.filter((a) => keyOf[a.source.id] === 'mosquito').reduce((s, a) => s + repeats(a), 0);
    const rodent = alarms.filter((a) => keyOf[a.source.id] === 'rodent').reduce((s, a) => s + repeats(a), 0);
    if (mosquito > 0) {
      add(mosquito >= 3 ? 'medium' : 'low', 'Pest Control', 'Auto-create spraying tasks',
        'Mosquito activity triggered ' + plural(mosquito, 'alarm') + '. Let the agent open a spraying work order when activity stays high for two readings in a row.');
    }
    if (rodent > 0) {
      add('medium', 'Pest Control', 'Dispatch technicians from trap alerts',
        'Animal control trap reported ' + plural(rodent, 'alarm') + '. The agent can assign the nearest technician and close the alarm once the trap is serviced.');
    }

    // 5. Environmental follow-up
    const env = alarms.filter((a) => ['water', 'soil'].includes(keyOf[a.source.id])).reduce((s, a) => s + repeats(a), 0);
    if (env > 0) {
      add('medium', 'Environmental', 'Link sensor alerts to irrigation and water supply',
        'Water / soil sensors raised ' + plural(env, 'alarm') + '. Let the agent adjust the irrigation schedule on low soil moisture and alert utilities on low water level.');
    }

    // 6. Silent devices
    const heard = new Set(alarms.concat(events).map((x) => x.source.id));
    const silent = devices.filter(({ mo }) => !heard.has(mo.id));
    if (silent.length) {
      add('medium', 'Data quality', 'Check silent devices',
        silent.map(({ mo }) => mo.name).join(', ') + ' sent no events or alarms in 7 days. The agent cannot act on devices it does not hear from.');
    }

    // 7. Availability monitoring
    const unmonitored = devices.filter(({ mo }) => !mo.c8y_RequiredAvailability);
    if (unmonitored.length) {
      add('low', 'Data quality', 'Enable availability monitoring',
        plural(unmonitored.length, 'device') + ' have no required interval set, so outages are invisible. Set one in Device management so the agent can detect offline devices.');
    }

    // 8. Warning noise
    const warnings = alarms.filter((a) => a.severity === 'WARNING').reduce((s, a) => s + repeats(a), 0);
    if (raised >= 5 && warnings / raised >= 0.6) {
      add('low', 'Alarm noise', 'Send warnings as a daily digest',
        Math.round((warnings / raised) * 100) + '% of this week’s alarms were warnings. Have the agent summarise them once a day instead of notifying on each one.');
    }

    if (!recs.length) {
      add('low', 'General', 'No issues found this week', 'Alarms were low and every device reported. A good time to add predictive rules, for example forecasting low water levels.');
    }

    const rank = { high: 0, medium: 1, low: 2 };
    recs.sort((a, b) => rank[a.priority] - rank[b.priority]);
    return { raised, critical, open: open.length, events: events.length, perCat, recs: recs.slice(0, 8) };
  }

  insightsHtml(week) {
    const r = this.analyse(week);
    const tile = (value, label) => '<div class="iot-kpi"><strong>' + value + '</strong><span>' + label + '</span></div>';
    const rows = Object.keys(CATEGORY_CARDS).map((c) => {
      const x = r.perCat[c];
      return '<tr><td>' + CATEGORY_LABEL[c] + '</td><td>' + x.alarms + '</td><td>' + x.critical + '</td><td>' + x.open + '</td><td>' + x.events + '</td></tr>';
    }).join('');
    const recs = r.recs.map((rec) =>
      '<li class="iot-rec"><span class="iot-pill is-' + rec.priority + '">' + rec.priority + '</span>' +
      '<div><p class="iot-rec-title">' + escapeHtml(rec.title) + '</p><p class="iot-rec-area">' + escapeHtml(rec.area) + '</p>' +
      '<p class="iot-rec-detail">' + escapeHtml(rec.detail) + '</p></div></li>').join('');

    return '<p class="iot-muted">' + shortDate(week.from) + ' – ' + shortDate(week.to) + ' · ' + plural(week.devices.length, 'device') + '</p>' +
      '<div class="iot-kpis">' + tile(r.raised, 'Alarms raised') + tile(r.critical, 'Critical') + tile(r.open, 'Still open') + tile(r.events, 'Events') + '</div>' +
      '<table class="iot-table"><thead><tr><th>Area</th><th>Alarms</th><th>Critical</th><th>Open</th><th>Events</th></tr></thead><tbody>' + rows + '</tbody></table>' +
      '<h4 class="iot-sub">Recommendations for the agent</h4><ul class="iot-recs">' + recs + '</ul>';
  }
}